CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(190) NULL UNIQUE,phone VARCHAR(40) NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,referral_code VARCHAR(20) NOT NULL UNIQUE,referred_by INT UNSIGNED NULL,status ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',is_admin TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(referred_by)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,balance DECIMAL(14,2) NOT NULL DEFAULT 0,total_invested DECIMAL(14,2) NOT NULL DEFAULT 0,total_withdrawn DECIMAL(14,2) NOT NULL DEFAULT 0,profit_30_days DECIMAL(14,2) NOT NULL DEFAULT 0,commission DECIMAL(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS packages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,price DECIMAL(14,2) NOT NULL,validity_days INT UNSIGNED NOT NULL,daily_profit DECIMAL(14,2) NOT NULL DEFAULT 0,total_return DECIMAL(14,2) NOT NULL DEFAULT 0,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_methods (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,account_name VARCHAR(120) NOT NULL,account_number VARCHAR(120) NOT NULL,display_order INT NOT NULL DEFAULT 1,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS referrals (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,referrer_id INT UNSIGNED NOT NULL,referee_id INT UNSIGNED NOT NULL,level TINYINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_ref(referrer_id,referee_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,token_hash CHAR(64) NOT NULL UNIQUE,user_id INT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS demo_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,type VARCHAR(30) NOT NULL,amount DECIMAL(14,2) NOT NULL,payment_method VARCHAR(100) NOT NULL,transaction_id VARCHAR(120) NOT NULL,account_details TEXT,proof_file VARCHAR(255),status ENUM('PENDING','APPROVED','REJECTED','COMPLETED') NOT NULL DEFAULT 'PENDING',reviewed_by INT UNSIGNED NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS uploads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,stored_name VARCHAR(255) NOT NULL,mime VARCHAR(80) NOT NULL,size BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT NOT NULL,is_public TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,action VARCHAR(160) NOT NULL,actor_id INT UNSIGNED NULL,meta_json TEXT,ip VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route VARCHAR(190),method VARCHAR(10),ip VARCHAR(80),status INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB;
